"""Recoverable trusted-editor HTML projection, no remote requests."""
import json
from pathlib import Path
from .attention_summary import summarize
from .attention_summary_view import render_summary
from .attention_positions import project_positions


def render(state):
    data = json.dumps(state, ensure_ascii=True).replace('<', '\\u003c')
    summary = summarize(state)
    saved = json.dumps(summary, ensure_ascii=True).replace('<', '\\u003c')
    positions = json.dumps(project_positions(summary), ensure_ascii=True).replace('<', '\\u003c')
    position_script = Path(__file__).with_name('attention_positions.js').read_text(encoding='utf-8')
    views = Path(__file__).with_name('attention_views.js').read_text(encoding='utf-8')
    script = Path(__file__).with_name('attention_editor.js').read_text(encoding='utf-8')
    return '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'none'"><title>B关注分析 · 可信编辑</title><style>
body{font:16px/1.6 system-ui,sans-serif;color:#17212e;background:#f7f9fb;max-width:1000px;margin:2rem auto;padding:0 1rem}h1{font-size:1.8rem}h2{font-size:1.3rem;margin-top:1.6rem}section{border:1px solid #c8d0da;border-radius:8px;padding:1rem;margin:1rem 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef1f5;padding:.7rem}label{display:block;margin:.7rem 0}input,select,textarea,button{font:inherit;max-width:100%;box-sizing:border-box}select,textarea,input{width:100%;padding:.5rem}select[multiple]{min-height:6rem}textarea{min-height:5rem}button{padding:.5rem 1rem;margin:.3rem .3rem .3rem 0;cursor:pointer}button:hover{background:#e3e8ee}button:active{background:#cbd5df}button:disabled{opacity:.6;cursor:default}:focus-visible{outline:2px solid #315879;outline-offset:2px}::selection{background:#cbdff0;color:#17212e}a{color:#254e70;text-underline-offset:.2em}#message{color:#80300c;min-height:1.6rem}small{color:#3f5267}#source{user-select:text}p,li{overflow-wrap:anywhere}summary{cursor:pointer}details{margin:1rem 0}@media(max-width:600px){body{margin:.5rem auto;padding:0 .6rem}section{padding:.7rem}button{white-space:normal}}
</style><h1>B关注分析</h1><p>仅供本地可信编辑。核对分析是否忠实，不表示认可B的专业判断。</p><p id="revision"></p><p id="material"></p><p>下载只生成草稿。请在本机窗口应用补丁，成功后重开本页核对。</p>
<section aria-label="保存结果与筛选" id="attention-views"><h2>查看已保存结果</h2><p id="view-version"></p><p>统计、矩阵和图始终属于已保存修订。表单更改或下载补丁后，请本机应用并重开。下方编辑区保留全材料，不随统计筛选隐藏。</p><p><a href="#view-overview">查看当前关注概览与回查集合</a></p><div id="view-controls"></div><div id="view-positions"></div><p id="view-hits" role="status"></p><div id="view-summary">''' + render_summary(summary) + '''</div><label><input type="checkbox" id="view-matrix-toggle"> 显示记录×主题/A矩阵</label><div id="view-matrix" hidden></div><label><input type="checkbox" id="view-graph-toggle"> 显示局部关系图</label><div id="view-graph" hidden></div><div id="view-detail"></div></section><section><h2>原话与原分</h2><label>评语记录<select id="record"></select></label><label>普通分区<select id="section"></select></label><p id="locator"></p><pre id="source" tabindex="0"></pre><div id="scores"></div><p id="record-note"></p></section>
<section><h2>观点与方面</h2><label>观点<select id="opinion"></select></label><label>观点方面<select id="facet"></select></label><p>先补全可分别核对的方面，再按方面拆成观点。拆合后旧关联留在旧身份并待核；新方面需重新核对主题及A对应。</p><button id="split" type="button">按方面拆分观点</button><label>选择同记录观点归并<select id="merge-opinions" multiple size="4"></select></label><button id="merge" type="button">归并所选观点</button><p>在上方原话中选中文字后采用；键盘也可用原话片段菜单。</p><button id="capture" type="button">采用选中文字</button><label>原话片段<select id="passage"></select></label><p id="evidence"></p><button id="evidence-add" type="button">追加为本方面证据</button><p id="facet-evidence-list"></p><label>分析解释<textarea id="interpretation"></textarea></label><label>方面类型<select id="facet-kind"><option value="content">内容关注</option><option value="disposition">流程或总体处置</option></select></label><label>核对状态<select id="status"><option value="working">工作解释</option><option value="needs_review">待核对</option><option value="confirmed">已核对分析</option><option value="withdrawn">撤回</option></select></label>
<details open><summary>方面限定与表达作用</summary><label>对象<input id="object"></label><label>判断方向<input id="direction"></label><label>程度<input id="degree"></label><label>否定<input id="negation"></label><label>理由<textarea id="reasons"></textarea></label><label>条件<textarea id="conditions"></textarea></label><label>动作<textarea id="actions"></textarea></label><label>例示<textarea id="examples"></textarea></label><label>备选<textarea id="alternatives"></textarea></label><label>本次表达作用<textarea id="function"></textarea></label><label>套话候选<select id="boilerplate"><option value="unknown">未判断</option><option value="true">是候选</option><option value="false">非候选</option></select></label></details>
<details open><summary>A对应与清单外内容</summary><p>同一方面可保留多个对应、清单外及未定范围。先将方面加入草稿，再编辑关联；原话片段菜单提供关联证据。</p><label>当前方面关联<select id="a-link"></select></label><label>关系种类<select id="a-kind"><option value="explicit">明确对应</option><option value="partial">部分对应</option><option value="related">内容相关</option><option value="undetermined">暂未定</option><option value="outside">清单外</option></select></label><label>A关注条目<select id="a-item"></select></label><p id="a-item-text"></p><label>具体范围<textarea id="a-scope"></textarea></label><label>对应或清单外理由<textarea id="a-reason"></textarea></label><label>关联核对状态<select id="a-status"><option value="working">工作解释</option><option value="needs_review">待核对</option><option value="confirmed">已核对分析</option><option value="withdrawn">撤回</option></select></label><p id="a-link-evidence"></p><button id="a-save" type="button">关联加入草稿</button><button id="a-remove" type="button">移除此关联</button></details>
<label>修改者声明<input id="actor" autocomplete="off"></label><label>修改理由<input id="reason" autocomplete="off"></label><button id="stage" type="button">加入草稿</button><button id="download" type="button" disabled>下载草稿补丁</button><p id="draft" role="status">没有未应用草稿</p><p id="message" role="alert"></p></section>
<section><h2>主题定义与成员依据</h2><label>主题<select id="theme"></select></label><label>主题名称<input id="theme-label"></label><label>定义与边界<textarea id="theme-definition"></textarea></label><label>父主题（可多选）<select id="theme-parents" multiple size="3"></select></label><button id="theme-stage" type="button">主题加入草稿</button><label>当前方面加入此主题的依据<textarea id="member-reason"></textarea></label><button id="member-add" type="button">加入当前方面</button><button id="member-withdraw" type="button">撤回当前方面的此项归属</button><p id="members"></p><details><summary>全部保存主题定义</summary><div id="saved-themes"></div></details></section>
<section><h2>有范围的关系</h2><label>关系<select id="relation"></select></label><label>关系端点方面<select id="relation-facet"></select></label><label>关系类型<input id="relation-type"></label><label>端点角色<input id="relation-role"></label><button id="endpoint-add" type="button">添加方面端点</button><label>已选端点<select id="endpoints" size="3"></select></label><button id="endpoint-remove" type="button">移除所选端点</button><label>方向或无方向说明<input id="relation-direction"></label><label>具体作用范围<textarea id="relation-scope"></textarea></label><label>工作读法<textarea id="relation-reading"></textarea></label><label>歧义与未决说明<textarea id="relation-ambiguity"></textarea></label><p>采用当前原话证据；多个出处可在选择片段后追加。</p><button id="relation-evidence" type="button">追加当前证据</button><p id="relation-evidence-list"></p><label>关系核对状态<select id="relation-status"><option value="working">工作解释</option><option value="needs_review">待核对</option><option value="confirmed">已核对分析</option><option value="withdrawn">撤回</option></select></label><button id="relation-stage" type="button">关系加入草稿</button><details><summary>全部保存关系与沿革（当前筛选的角色/范围见上方明细）</summary><div id="saved-relations"></div></details></section>
<section><h2>全材料解释与沿革</h2><details><summary>展开全部保存解释与撤回/替换历史（不随上方筛选）</summary><h3>当前有效解释</h3><div id="saved"></div><details><summary>撤回和被替换解释（历史）</summary><div id="saved-archive"></div></details></details></section><section><h2>A工作参照</h2><p id="a-version"></p><details><summary>A条目原文与历史版本</summary><div id="a-items"></div></details></section><section><h2>保存历史</h2><div id="history"></div></section><script id="attention-data" type="application/json">''' + data + '</script><script id="attention-summary-data" type="application/json">' + saved + '</script><script id="attention-position-data" type="application/json">' + positions + '</script><script>' + position_script + '</script><script>' + views + '</script><script>' + script + '</script></html>'
